extern int upsideDown;

// Primary Author: Samuel Lamore
// Print mario at his current coordinates
void set_mario_position(int x, int y) {
    if (y < 3) { // set bounds
        y = 3;
    } else if (y > 14) {
        y = 14;
    }
    if (x < 1) {
        x = 1;
    } else if (x > 98) {
        x = 98;
    }

    for (int y = 0; y < 16; y++) {
        for (int x = 0; x < 100; x++) {
            mario_layer[y][x] = ' ';
        }
        mario_layer[y][100] = '\0';
    }

    //mario shape
    if (!upsideDown) {
        mario_layer[y][x]     = '/';
        mario_layer[y][x+1]   = '\\';
        mario_layer[y-1][x]   = '[';
        mario_layer[y-1][x+1] = ']';
    } else {
        mario_layer[y-1][x]     = '\\';
        mario_layer[y-1][x+1]   = '/';
        mario_layer[y][x]   = '[';
        mario_layer[y][x+1] = ']';
    }
}

int scrollX = 0; // how many horizontal units have been scrolled

// Primary Author: Samuel Lamore
// Shift a row forward one char
void shift_row(char *row) {
    for (int x = 0; row[x] != '\0'; x++) {
        row[x] = row[x+1];
    }
}

// Primary Author: Samuel Lamore
// Get the next char from the initializer layer and add it to the end of the drawing layers
void update_row(char *row, int i, int y) {
    row[99] = layer_init[i][y][scrollX+99];
}



// Primary Author: Samuel Lamore
// Scroll the layers of the level that are supposed to move
void scroll_level() {
    //scrolls background, ground, and obstacles layers
    scrollX++;

    for (int i = BG_LAYER; i < MARIO_LAYER; i++) {
        for (int y = 0; y < 16; y++) {
            shift_row(layers[i][y]);
            update_row(layers[i][y], i, y);
        }
    } 
}

// Primary Author: Samuel Lamore
// Get rid of the "speed up" graphic
void clear_speed_up_graphic() {
    for (int y = 0; y < 4; y++) {
        for (int x = 0; x < 44; x++) {
            speed_up_layer[y+2][x+28] = ' ';
        }
    }
}

// Primary Author: Samuel Lamore
// Print "SPEED UP" on screen to indicate the speed increasing
void render_speed_up_graphic(int timer) {
    for (int y = 0; y < 4; y++) {
        for (int x = 0; x < 44; x++) {
            speed_up_layer[y+2][x+28] = speed_up[y][x];
        }
    }

    if (timer % 14 == 0) {
        init_pair(18, COLOR256(1, 0, 0), COLOR_BLACK);
    } else if (timer % 14 == 7) {
        init_pair(18, COLOR256(5, 1, 1), COLOR_BLACK);
    }
}


short r = 0;
short g = 0;
short b = 0;

// Primary Author: Samuel Lamore
// Cycle through the rainbow for the star powerup
void update_invincibility_colors(int timer, int invincTimer) {
    int hue = (timer << 3) % 360;
    float sat = 1.0f;
    float val = 0.8f;

    if (invincTimer < 15 && invincTimer > 0) {
        if ((invincTimer % 6) <= 2) {
            val = 0.6f;
            sat = 0.2f;
        }
    }

    hsv_to_rgb(hue, sat, val, &r, &g, &b);

    init_pair(19, COLOR256(r, g, b), COLOR_BLACK);
    if (invincTimer > 0) {
        //update mario layer and border layer
        init_pair(4, COLOR256(r, g, b), COLOR_BLACK);
        init_pair(5, COLOR256(r, g, b), COLOR256(r, g, b));
    } else {
        init_pair(4, COLOR_RED, COLOR_BLACK);  // restore mario layer
        init_pair(5, COLOR256(0, 0, 1), COLOR256(0, 0, 1));  // restore border layer
    }
}


// Primary Author: Samuel Lamore
// Initialize colors
void set_up_colors() {
    start_color();
    init_pair(1, COLOR256(4, 5, 5), COLOR_BLACK);   // background layer
    init_pair(2, COLOR_GREEN, COLOR_BLACK);  // ground layer
    init_pair(3, COLOR256(5, 2, 0), COLOR_BLACK);  // obstacles layer
    init_pair(4, COLOR_RED, COLOR_BLACK);  // mario layer
    init_pair(5, COLOR256(0, 0, 1), COLOR256(0, 0, 1));  // border layer
    init_pair(6, COLOR_BLACK, COLOR_BLACK);  // EMPTY layer
    init_pair(7, COLOR_YELLOW, COLOR_BLACK);  // Coin layer
    init_pair(17, COLOR256(4, 1, 4), COLOR_BLACK);  // ground layer (upside down)
    init_pair(18, COLOR256(5, 1, 1), COLOR_BLACK);  // hud layer (speed up graphic)
    init_pair(19, COLOR_YELLOW, COLOR_BLACK);  // Star layer
}


// Primary Author: Samuel Lamore
// Add a cloud to the background at the given coordinates
void add_cloud(int x, int y, int cloud) {
    for (int yCord = 0; yCord < CLOUD_HEIGHT; yCord++) {
        for (int xCord = 0; clouds[cloud][yCord][xCord] != '\0'; xCord++) {
            if (clouds[cloud][yCord][xCord] != ' ' && background_layer_init[y+yCord][x+xCord] == ' ') {
                background_layer_init[y+yCord][x+xCord] = clouds[cloud][yCord][xCord];
            }
        }
    }
}


// Primary Author: Samuel Lamore
// Determine random cloud generation
void add_background_elements() {
    for (int i = 0; i < (LEVEL_SIZE/30) - 3; i++) {
        if ((rand() % 3) != 0 && (i*30 < 400 || i*30 > 700)) {
            int height = 1 + (rand() % 6);
            int xOffset = rand() % 10;
            int cloud = rand() % NUM_CLOUDS;
            add_cloud((i*30) + xOffset, height, cloud);
        }
    }
}

// Primary Author: Samuel Lamore
// Copy the contents of the initializer layers into the drawing layers
void init_layers() {
    add_background_elements();
    for (int i = 0; i < NUM_LAYERS; i++) {
        for (int y = 0; y < 16; y++) {
            strncpy(layers[i][y], layer_init[i][y], 100);
            layers[i][y][100] = '\0';  // ensure null-terminated
        }
    }
}


// Primary Author: Samuel Lamore
// Combine the drawing layers together into the main screen matrix
void assemble_layers() {
    //first: clear screen matrix
    for (int y = 0; y < 16; y++) {
        for (int x = 0; x < 100; x++) {
            screen[y][x] = ' ';
            color_screen[y][x] = 6;
        }
        screen[y][100] = '\0';
    }

    //then: apply layers
    for (int i = 0; i < NUM_LAYERS; i++) {
        for (int y = 0; y < 16; y++) {
            for (int x = 0; layers[i][y][x] != '\0' && x < 100; x++) {
                if (layers[i][y][x] != ' ') {
                    screen[y][x] = layers[i][y][x];
                    if (i == GROUND_LAYER && (scrollX + x) >= 436 && ((scrollX + x) < 695) && y < 8) {
                        color_screen[y][x] = 17;
                    } else {
                        color_screen[y][x] = layer_colors[i];
                    }
                }
            }
        }
    }
}

// Primary Author: Samuel Lamore
// Render each char of the screen matrix
void render_screen() {
    for (int y = 0; y < 16; y++) {
        for (int x = 0; x < 100; x++) {
            attron(COLOR_PAIR(color_screen[y][x]));
            mvaddch(y, x, screen[y][x]);
            attroff(COLOR_PAIR(color_screen[y][x]));
        }
    }
    refresh();
}